        // Circuit health monitor: a background thread that periodically closes
        // weak conflux legs so tor rebuilds them with fresh, higher-quality
        // circuits. Disabled with --no-circuit-watch. Weakness is judged purely
        // relative and GLOBALLY: the top watchRttPct% of all linked legs across
        // every set by RTT are weak candidates, so a single slow leg of any set
        // is pruned just like the weak legs of a large set, with no absolute
        // thresholds. A leg must stay weak for --watch-strikes consecutive
        // passes before a close (default 1), and the single best (lowest RTT)
        // leg in the pool is never a candidate. The percentage is settable from
        // the settings menu (data\circuit-watch-pct.txt) or via --watch-rtt-pct.
        // Other knobs: --watch-unlinked-strikes (consecutive unlinked passes
        // before a stuck leg is closed), plus --watch-interval, --watch-cooldown
        // and --watch-max-per-pass.
        private static volatile bool circuitWatchStop;
        private static bool circuitWatchEnabled = true;
        private static int watchRttPct = ReadConfluxSetting(WatchRttPctFile, 0);
        private static int watchStrikes = 1;
        private static int watchUnlinkedStrikes = 4;
        private static int watchUnlinkedGraceS = 120;
        private static int watchMaxPerPass = 6;
        private static int watchIntervalS = 10;
        private static int watchCooldownS = 20;

        // Per-circuit consecutive-bad counters for the monitor (persist across
        // passes so a single RTT spike never prunes a healthy leg).
        private static readonly Dictionary<string, int> weakStrikes =
            new Dictionary<string, int>();
        private static readonly Dictionary<string, int> unlinkedStrikes =
            new Dictionary<string, int>();
        // First pass a circuit was seen UNLINKED, so legs still legitimately
        // building under load are never killed while they are young.
        private static readonly Dictionary<string, DateTime> unlinkedFirstSeen =
            new Dictionary<string, DateTime>();

        // Guards console output shared between the main thread (keep-alive /
        // menu output) and the circuit monitor thread, so lines never
        // interleave mid-write.
        private static readonly object consoleLock = new object();

        // During tunnel warmup the watch cooldown is relaxed so weak legs are
        // replaced immediately instead of waiting out the normal gap.
        private static volatile bool circuitWatchWarmup;

        // After bootstrap the circuit monitor keeps its relaxed cooldown for a
        // short window while the first conflux legs build, then enforces the
        // normal gap between pruning passes.
        private static int warmupRelaxSeconds = 90;

        [DllImport("wininet.dll", SetLastError = true)]
        private static extern bool InternetSetOption(IntPtr h, int option, IntPtr buffer, int length);

        private static bool ProxyIsOurs()
        {
            try
            {
                using (RegistryKey k = Registry.CurrentUser.OpenSubKey(ProxyKey))
                {
                    if (k == null) return false;
                    object en = k.GetValue("ProxyEnable");
                    object ps = k.GetValue("ProxyServer");
                    return en is int && (int)en == 1 &&
                           ps is string &&
                           ((string)ps).IndexOf("127.0.0.1:8118",
                                                StringComparison.OrdinalIgnoreCase) >= 0;
                }
            }
            catch { return false; }
        }

        private static string savedProxy;
        private static string savedProxyOverride;
        private static bool savedProxyOn;

        private static void SetSystemProxy(bool on)
        {
            if (!on && !ProxyIsOurs()) return;
            try
            {
                using (RegistryKey k = Registry.CurrentUser.CreateSubKey(ProxyKey))
                {
                    if (on)
                    {
                        if (!ProxyIsOurs())
                        {
                            savedProxy = k.GetValue("ProxyServer") as string ?? "";
                            savedProxyOverride = k.GetValue("ProxyOverride") as string ?? "";
                            object en = k.GetValue("ProxyEnable");
                            savedProxyOn = en is int && (int)en == 1;
                        }
                        k.SetValue("ProxyEnable", 1, RegistryValueKind.DWord);
                        k.SetValue("ProxyServer", "127.0.0.1:8118", RegistryValueKind.String);
                        k.SetValue("ProxyOverride", "<local>", RegistryValueKind.String);
                    }
                    else
                    {
                        k.SetValue("ProxyEnable", savedProxyOn ? 1 : 0, RegistryValueKind.DWord);
                        k.SetValue("ProxyServer", savedProxy ?? "", RegistryValueKind.String);
                        k.SetValue("ProxyOverride", savedProxyOverride ?? "", RegistryValueKind.String);
                    }
                }
            }
            catch { }
            InternetSetOption(IntPtr.Zero, InternetOptionSettingsChanged, IntPtr.Zero, 0);
            InternetSetOption(IntPtr.Zero, InternetOptionRefresh, IntPtr.Zero, 0);
        }

        private static bool IsAdmin()
        {
            try
            {
                using (var id = System.Security.Principal.WindowsIdentity.GetCurrent())
                {
                    var p = new System.Security.Principal.WindowsPrincipal(id);
                    return p.IsInRole(System.Security.Principal.WindowsBuiltInRole.Administrator);
                }
            }
            catch { return false; }
        }

        private static string ReadTunState()
        {
            try
            {
                if (File.Exists(TunStateFile))
                {
                    foreach (string line in File.ReadAllLines(TunStateFile))
                        if (line.TrimStart().StartsWith("status="))
                            return line.TrimStart().Substring(7).Trim();
                }
            }
            catch { }
            return "off";
        }

        // TUN counts as ON when the state file says so OR a tun-helper keeper is
        // actually running. The state file can be emptied/left stale by a failed
        // enable; only trusting it made "T" keep re-enabling instead of turning
        // the tunnel off.
        private static bool TunActive()
        {
            if (ReadTunState() == "on") return true;
            try
            {
                foreach (Process p in Process.GetProcessesByName("tun-helper"))
                    if (!p.HasExited &&
                        p.MainModule.FileName.Equals(TunHelperExe, StringComparison.OrdinalIgnoreCase))
                        return true;
            }
            catch { }
            return false;
        }

        private static string ReadTunResult()
        {
            try { if (File.Exists(TunResultFile)) return File.ReadAllText(TunResultFile).Trim(); }
            catch { }
            return "";
        }

        private static bool SpawnElevated(string args, bool wait)
        {
            try
            {
                // Tell the elevated helper where the data dir is. It used to sit
                // next to data\ and derive it from its own location; now it ships
                // inside data\, so this keeps state/result/stop files in sync.
                Environment.SetEnvironmentVariable("TUN_DATA_DIR", DataDir,
                                                   EnvironmentVariableTarget.Process);
                var psi = new ProcessStartInfo
                {
                    FileName = TunHelperExe,
                    Arguments = args,
                    UseShellExecute = true,
                    Verb = "runas",
                    WindowStyle = ProcessWindowStyle.Hidden
                };
                using (Process p = Process.Start(psi))
                {
                    if (wait) p.WaitForExit();
                }
                return true;
            }
            catch { return false; }
        }

        private static void ToggleTun()
        {
            if (TunActive())
            {
                TurnTunOff();
            }
            else
            {
                if (!IsAdmin()) Console.WriteLine("  TUN mode needs Administrator - accept the UAC prompt.");
                Console.WriteLine("  Turning TUN ON (all traffic via Tor)...");
                if (!SpawnElevated("on", false))
                {
                    Console.WriteLine("  TUN enable cancelled.");
                    return;
                }
                string last = "";
                for (int i = 0; i < 20; i++)
                {
                    Thread.Sleep(1000);
                    last = ReadTunResult();
                    if (last.StartsWith("on:") || last.StartsWith("error:")) break;
                }
                Console.WriteLine("  " + last);
            }
        }

        private static void TurnTunOff()
        {
            Console.WriteLine("  Turning TUN OFF...");
            try { File.WriteAllText(TunStopFile, "stop", new UTF8Encoding(false)); } catch { }
            for (int i = 0; i < 40 && TunActive(); i++) Thread.Sleep(500);
            if (!TunActive()) { Console.WriteLine("  TUN OFF"); return; }
            Console.WriteLine("  keeper did not stop; forcing teardown (UAC)...");
            if (SpawnElevated("off", true))
                Console.WriteLine("  " + (TunActive() ? "TUN still ON - check data\\tun-result.txt" : "TUN OFF"));
            else
                Console.WriteLine("  teardown cancelled - TUN still ON");
        }

        private static void Cleanup()
        {
            if (cleaned) return;
            cleaned = true;
            StopKeepAlive();
            circuitWatchStop = true;
            if (TunActive())
            {
                try { File.WriteAllText(TunStopFile, "stop", new UTF8Encoding(false)); } catch { }
                for (int i = 0; i < 8; i++)
                {
                    Thread.Sleep(500);
                    if (!TunActive()) break;
                }
                if (TunActive())
                    try { SpawnElevated("off", true); } catch { }
            }
            if (torProc != null)
            {
                try { if (!torProc.HasExited) { torProc.Kill(); torProc.WaitForExit(5000); } }
                catch { }
            }
            StopXray();
            SetSystemProxy(false);
        }

