        private static void PromptConfluxRttPct()
        {
            Console.WriteLine("  ConfluxSetRttPct = when picking a set, only use the best");
            Console.WriteLine("    this-many percent of sets (lowest best-leg RTT);");
            Console.WriteLine("    0 = off (use all sets), 100 = same, e.g. 25 = top quarter).");
            Console.Write("  New value (Enter = keep " + confluxRttPct + "): ");
            string input;
            try { input = Console.ReadLine(); }
            catch { return; }
            if (string.IsNullOrWhiteSpace(input)) return;
            int v;
            if (int.TryParse(input.Trim(), out v) && v >= 0 && v <= 100)
            {
                confluxRttPct = v;
                WriteConfluxSetting(ConfluxRttPctFile, v);
                Console.WriteLine("  Best-% set filter set to " + (v == 0 ? "off" : v + "%") + ".");
            }
            else
            {
                Console.WriteLine("  Invalid value (0-100).");
            }
        }

        private static void PromptWatchRttPct()
        {
            Console.WriteLine("  Weak legs (top %) = the this-many percent of all linked legs");
            Console.WriteLine("    (across EVERY set, compared globally) with the highest RTT");
            Console.WriteLine("    are weak and get closed. Fully relative: no absolute ms");
            Console.WriteLine("    threshold, e.g. 30 = the slowest 30% of the whole linked pool.");
            Console.WriteLine("    The single best leg in the pool is never closed. 0 = off.");
            Console.Write("  New value (Enter = keep " + watchRttPct + "): ");
            string input;
            try { input = Console.ReadLine(); }
            catch { return; }
            if (string.IsNullOrWhiteSpace(input)) return;
            int v;
            if (int.TryParse(input.Trim(), out v) && v >= 0 && v <= 100)
            {
                watchRttPct = v;
                WriteConfluxSetting(WatchRttPctFile, v);
                Console.WriteLine("  Weak-leg top-% set to " + (v == 0 ? "off" : v + "%") + ".");
            }
            else
            {
                Console.WriteLine("  Invalid value (0-100).");
            }
        }

        private static Process FindXray()
        {
            foreach (Process p in Process.GetProcessesByName("xray"))
            {
                try
                {
                    if (p.MainModule.FileName.Equals(XrayExe, StringComparison.OrdinalIgnoreCase))
                        return p;
                }
                catch { }
            }
            return null;
        }

        // Writes/uses data\xray\config.json: a local SOCKS inbound whose freedom
        // outbound applies TCP fragmentation to every connection. tor sends all
        // of its guard/bridge TLS through this SOCKS proxy (Socks5Proxy in
        // torrc), so the split ClientHello hides the Tor handshake from
        // packet-length/SNI based DPI. The config ships with the release
        // (repo: configs\xray-config.json) and is never generated by the
        // launcher - if it is missing, fragment is disabled for the run.
        private static bool StartXray()
        {
            try
            {
                if (!File.Exists(XrayExe))
                {
                    Console.WriteLine("[!] xray.exe not found in " + DataDir +
                                      " - fragment disabled for this run.");
                    return false;
                }
                if (!File.Exists(XrayConfig))
                {
                    Console.WriteLine("[!] xray config not found (" + XrayConfig +
                                      ") - fragment disabled for this run.");
                    return false;
                }
                ProcessStartInfo psi = new ProcessStartInfo
                {
                    FileName = XrayExe,
                    Arguments = "run -c xray\\config.json",
                    WorkingDirectory = DataDir,
                    UseShellExecute = false,
                    CreateNoWindow = true
                };
                Process p = Process.Start(psi);
                xrayProc = p;
                Console.WriteLine("xray (fragment) started (PID " + p.Id +
                                  ") on 127.0.0.1:" + FragmentSocksPort +
                                  " using xray\\config.json");
                return true;
            }
            catch (Exception ex)
            {
                Console.WriteLine("[x] failed to start xray: " + ex.Message);
                return false;
            }
        }

        private static void StopXray()
        {
            Process p = xrayProc;
            xrayProc = null;
            if (p != null)
            {
                try { if (!p.HasExited) { p.Kill(); p.WaitForExit(5000); } }
                catch { }
            }
            p = FindXray();
            if (p != null)
            {
                try { p.Kill(); p.WaitForExit(5000); } catch { }
            }
        }

        // Strategy for a run: env override (bench) > saved choice > ultimate.
        private static int ResolveStrategy()
        {
            string env = Environment.GetEnvironmentVariable("BENCH_STRATEGY");
            if (!string.IsNullOrEmpty(env))
            {
                int s = ParseStrategy(env);
                if (s >= 0) return s;
            }
            int last = ReadLastStrategy();
            return last >= 0 ? last : StrategyNames.Length - 1;
        }

