        // Interactive startup: pick connection mode and strategy level, then start.
        private static void ShowMainMenu(out int mode, out int strategy, out bool fragment)
        {
            mode = ReadLastMode();
            if (mode < 0) mode = 0;
            strategy = ReadLastStrategy();
            if (strategy < 0) strategy = StrategyNames.Length - 1;
            fragment = ReadFragmentSetting();
            while (true)
            {
                Console.WriteLine();
                Console.WriteLine("  ==============================");
                Console.WriteLine("         TorJet v" + TorJetVersion.App);
                Console.WriteLine("  ==============================");
                Console.WriteLine();
                Console.WriteLine("    1)  Start Tor");
                Console.WriteLine("    2)  Connection mode   : " + ModeNames[mode]);
                Console.WriteLine("    3)  Settings");
                Console.WriteLine("    4)  Quit");
                Console.WriteLine();
                Console.Write("  Enter 1-4 (Enter = Start): ");
                string input;
                try { input = Console.ReadLine(); }
                catch { mode = -1; return; }
                if (string.IsNullOrWhiteSpace(input)) return;
                int n;
                if (int.TryParse(input.Trim(), out n))
                {
                    if (n == 1) return;
                    if (n == 2)
                    {
                        int m = ShowMenu();
                        if (m >= 0) { mode = m; WriteModeFile(mode); }
                    }
                    else if (n == 3)
                    {
                        ShowSettingsMenu(ref strategy, ref fragment);
                    }
                    else if (n == 4) { mode = -1; return; }
                    else Console.WriteLine("  Invalid choice, try again.");
                }
                else
                {
                    int m = ParseMode(input.Trim());
                    if (m >= 0) { mode = m; WriteModeFile(mode); }
                    else
                    {
                        int s = ParseStrategy(input.Trim());
                        if (s >= 0) { strategy = s; WriteStrategyFile(strategy); }
                        else Console.WriteLine("  Invalid choice, try again.");
                    }
                }
            }
        }

